36	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdvice;
37	
38	/**
39	 * Rejects a create-owner request once 100 or more owners have already been created today
40	 * (by registrationDate), responding 429 Too Many Requests. Applies only to the create
41	 * endpoint so updates are unaffected.
42	 */
43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerDailyLimitAdvice implements RequestBodyAdvice {
46	
47	    private static final int DAILY_LIMIT = 100;
48	
49	    private final ClinicService clinicService;
50	
51	    public OwnerDailyLimitAdvice(ClinicService clinicService) {
52	        this.clinicService = clinicService;
53	    }
54	
55	    @Override
56	    public boolean supports(MethodParameter methodParameter, Type targetType,
57	                            Class<? extends HttpMessageConverter<?>> converterType) {
58	        Method method = methodParameter.getMethod();
59	        return OwnerFieldsDto.class.equals(targetType) && method != null
60	            && "addOwner".equals(method.getName());
61	    }
62	
63	    @Override
64	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
65	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
66	        if (createdTodayCount() >= DAILY_LIMIT) {
67	            throw new DailyLimitReachedException();
68	        }
69	        return body;
70	    }
71	
72	    private int createdTodayCount() {
73	        LocalDate today = org.springframework.samples.petclinic.util.BusinessDays.toBusinessDay(LocalDate.now());
74	        int count = 0;
75	        for (Owner existing : clinicService.findAllOwners()) {
76	            if (today.equals(existing.getRegistrationDate())) {
77	                count++;
78	            }
79	        }
80	        return count;
81	    }
82	
83	    @Override
84	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
85	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
86	        return body;
87	    }
88	
89	    @Override
90	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
91	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
92	        return inputMessage;
93	    }
94	
95	    @ExceptionHandler(DailyLimitReachedException.class)
96	    @ResponseBody
97	    public ResponseEntity<Void> handleDailyLimitReached(DailyLimitReachedException e) {
98	        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).build();
99	    }
